"""Assumption-only membership model. Writes only scenario-model.json."""
from pathlib import Path
import json
from math import ceil
D = Path(__file__).resolve().parent

def calc(c):
    task_cost = sum(c[k] for k in ('inference', 'data', 'testing_qa', 'infrastructure'))
    usage_cost = c['tasks_per_member'] * task_cost
    replacement_cac = c['monthly_churn'] * c['acquisition_cost']
    variable = usage_cost + c['support_per_member'] + c['distribution_per_member'] + replacement_cac + c['monthly_price'] * c['payment_fee_fraction']
    contribution = c['monthly_price'] - variable
    return dict(tasks=c['members'] * c['tasks_per_member'], revenue=c['members'] * c['monthly_price'], task_cost=task_cost, variable_cost_per_member=variable, contribution_per_member=contribution, replacement_members=c['members'] * c['monthly_churn'], replacement_acquisition_cost=c['members'] * replacement_cac, monthly_operating_contribution=c['members'] * contribution - c['fixed'], break_even_members=ceil(c['fixed'] / contribution) if contribution > 0 else None, initial_acquisition_cash=c['members'] * c['acquisition_cost'])

cases = [
 dict(name='low', members=200, monthly_price=5, tasks_per_member=3, inference=.12, data=.08, testing_qa=.20, infrastructure=.02, support_per_member=1.2, distribution_per_member=.4, monthly_churn=.12, acquisition_cost=25, payment_fee_fraction=.04, fixed=10000),
 dict(name='base', members=2000, monthly_price=8, tasks_per_member=4, inference=.06, data=.04, testing_qa=.10, infrastructure=.01, support_per_member=.75, distribution_per_member=.3, monthly_churn=.08, acquisition_cost=20, payment_fee_fraction=.04, fixed=20000),
 dict(name='high', members=10000, monthly_price=10, tasks_per_member=5, inference=.04, data=.03, testing_qa=.06, infrastructure=.01, support_per_member=.5, distribution_per_member=.25, monthly_churn=.04, acquisition_cost=15, payment_fee_fraction=.04, fixed=45000)]
variants = [('base', {}), ('half members', {'members':1000}), ('price $5', {'monthly_price':5}), ('double usage', {'tasks_per_member':8}), ('double inference', {'inference':.12}), ('double testing QA', {'testing_qa':.20}), ('churn 16%', {'monthly_churn':.16}), ('CAC $40', {'acquisition_cost':40}), ('zero merchant revenue', {})]
out = dict(as_of='2026-11-03', currency='USD', period='one steady-state month', status='Every numeric scenario input is an explicit original assumption, not measured demand, a supplier quote, empirical willingness to pay, or a forecast. No merchant revenue in any case.', unit='paying consumer member; task usage includes failures, abstentions and free-trial costs allocated to paying members', formula='members * (monthly_price * (1-payment_fee_fraction) - tasks_per_member*(inference+data+testing_qa+infrastructure) - support_per_member - distribution_per_member - monthly_churn*acquisition_cost) - fixed', ranking_policy='Only buyer fit, verified outcomes and true landed cost determine ranking. No sponsored placement, auction or commission-based catalog exclusion.', cases=[c | {'outputs':calc(c)} for c in cases], base_sensitivities=[dict(name=n, changes=v, **calc(cases[1]|v)) for n,v in variants], revenue_tests=[dict(line='flat completed-purchase fee', can_anyone_pay_to_rank=False, included_in_core=False, condition='Unvalidated optional route; uniform effective fee, nonpaying-product inclusion, disclosed charge and independent ranking; no fee in forecasts.'), dict(line='consumer membership', can_anyone_pay_to_rank=False, included_in_core=True, condition='Same ranking for members and nonmembers; payment buys research access/service, never product preference.'), dict(line='uniform effective fee or rebate affiliate', can_anyone_pay_to_rank=False, included_in_core=False, condition='Unvalidated optional route; equal effective fee/rebate, all eligible and nonpaying candidates considered, revenue system firewalled; written permission and settled receipts required.'), dict(line='post-ranking aggregate brand insights', can_anyone_pay_to_rank=False, included_in_core=False, condition='Unvalidated; explicit separate consent, proposed minimum cohort 30 distinct consenting buyers, suppression against reidentification, equal published price, no merchant ranking influence or raw chat resale.'), dict(line='sponsored placements / auctions / differentiated profitable links', can_anyone_pay_to_rank=True, included_in_core=False, condition='Prohibited, not upside.')], budget_90_days=dict(founder_stipend=15000,contract_engineering=12000,test_devices=6000,legal_privacy_and_licenses=5000,data_compute=2000,research_ops=3000,reserve=2000,total=45000), accounting_limits=['Fixed costs cover ongoing lean payroll/admin/legal amortization; task QA is incremental, avoid double counting.', 'Replacement CAC models steady-state churn only; initial acquisition and growth acquisition are separate cash requirements, not silently free.', 'No guarantee underwriting, merchant revenue, brand insight revenue, taxes, financing, equity dilution or founder dividends modeled.', 'A dock purchase is infrequent; recurring cross-task membership value is unproven. Usage and retention require observation.', 'Cash stress assumes two months of fixed and variable spend without receipts; not an empirical settlement forecast.'])
(D/'scenario-model.json').write_text(json.dumps(out, indent=2)+'\n')
for c in out['cases']:
 z=c['outputs']; print(f"{c['name']}: revenue={z['revenue']:.2f} variable/member={z['variable_cost_per_member']:.2f} contribution/member={z['contribution_per_member']:.2f} operating={z['monthly_operating_contribution']:.2f} break_even_members={z['break_even_members']} initial_CAC_cash={z['initial_acquisition_cash']:.2f}")
for v in out['base_sensitivities']: print(f"sensitivity {v['name']}: operating={v['monthly_operating_contribution']:.2f} break_even_members={v['break_even_members']}")
b=out['cases'][1]; print(f"two_month_base_no_receipts_reserve={2*(b['fixed']+b['members']*b['outputs']['variable_cost_per_member']):.2f}")
assert sum(v for k,v in out['budget_90_days'].items() if k!='total') == 45000
print('90_day_budget=45000')
